function t(pair){return L==='th'?pair[1]:pair[0]}

/* HEADER (fixed once per data load, re-applied on language toggle) */
function renderHeader(){
  g('df-name').textContent=d.name||t(STR.unnamed);
  g('df-alias').textContent=d.alias?(t(STR.akaPrefix)+d.alias+t(STR.akaSuffix)):'';
  var tier=d.tier||'';
  var tierInfo=TIER_INFO[tier];
  var tb=g('df-tier-badge');
  if(tierInfo){
    tb.textContent=t([tierInfo.en,tierInfo.th]);
    tb.style.color=tierInfo.color;
    tb.style.background=tierInfo.color+'22';
    tb.style.border='1px solid '+tierInfo.color+'66';
  }else{
    tb.textContent=t(STR.unregistered);
    tb.style.color='var(--mu)';
    tb.style.border='1px solid var(--bd2)';
  }
}
if(d.avatar){
  var img=document.createElement('img');
  img.src='https://files.catbox.moe/'+d.avatar;
  img.onerror=function(){this.style.display='none'};
  g('df-avatar').appendChild(img);
}

/* PARTICULARS */
function renderParticulars(){
  g('f-age').textContent=d.age!=null&&d.age!==''?d.age:t(STR.dash);
  g('f-origin').textContent=d.origin||t(STR.dash);
  g('f-occ').textContent=d.occupation||t(STR.dash);
}

/* STANDING + LADDER */
var seq=d.sequence!=null&&d.sequence!==''?parseInt(d.sequence,10):null;
function renderStanding(){
  var tier=d.tier||'';
  var tierInfo=TIER_INFO[tier];
  if(tierInfo){
    g('df-tier-nm').textContent=t([tierInfo.en,tierInfo.th]);
    g('df-tier-ds').textContent=t([tierInfo.enDesc,tierInfo.thDesc]);
  }else{
    g('df-tier-nm').textContent=t(STR.unregistered);
    g('df-tier-ds').textContent=t(STR.noStanding);
  }
  var pathTh=d.pathway?(PATHWAYS_TH[d.pathway]||d.pathway):null;
  g('df-seq').textContent=(d.pathway&&seq!=null)?((L==='th'?'ลำดับ ':'Sequence ')+seq):t(STR.dash);
  g('df-path-nm').textContent=d.pathway?(L==='th'?pathTh:d.pathway):t(STR.noPathway);
  if(!d.sequenceTitle){g('df-seq-title').textContent='';}
  else if(seq===9){g('df-seq-title').textContent=L==='th'?(SEQ9_TITLE_TH[d.sequenceTitle]||d.sequenceTitle):d.sequenceTitle;}
  else{g('df-seq-title').textContent=d.sequenceTitle;}

  var rail=g('df-ladder-rail');
  var lh='';
  var activeSeq=(seq!=null?seq:-1);
  for(var s=0;s<=9;s++){
    lh+='<div class="df-lnode'+(s===activeSeq?' on':'')+'"></div>';
    if(s<9)lh+='<div class="df-lseg"></div>';
  }
  rail.innerHTML=lh;
}

function noteBlock(val){return val?('<div class="df-note">'+esc(val)+'</div>'):'';}

function renderSpirit(){
  var sb=d.spiritualBody||{};
  var h='<div class="df-sec"><svg width="12" height="12" viewBox="0 0 12 12" fill="none"><path d="M6 0 L7 5 L12 6 L7 7 L6 12 L5 7 L0 6 L5 5 Z" fill="#C0A050"/></svg><span class="t">'+t(['Spiritual Body','กายจิต'])+'</span><span class="ln"></span></div>';
  h+=noteBlock(sb.quality)||('<div class="df-empty">'+t(STR.qualityEmpty)+'</div>');
