function renderPersona(){
  var h='';
  if(d.appearance||d.nature||d.history){
    h+='<div class="df-sec"><svg width="12" height="12" viewBox="0 0 12 12" fill="none"><path d="M6 0 L7 5 L12 6 L7 7 L6 12 L5 7 L0 6 L5 5 Z" fill="#C0A050"/></svg><span class="t">'+t(['Persona','ประวัติ'])+'</span><span class="ln"></span></div>';
    h+=noteBlock(d.appearance);
    h+=noteBlock(d.nature);
    h+=noteBlock(d.history);
  }
  g('persona-wrap').innerHTML=h;
  g('scene-wrap').innerHTML=d.openingScene?
    ('<div class="df-sec"><svg width="12" height="12" viewBox="0 0 12 12" fill="none"><path d="M6 0 L7 5 L12 6 L7 7 L6 12 L5 7 L0 6 L5 5 Z" fill="#C0A050"/></svg><span class="t">'+t(['Opening Scene','ฉากเริ่มต้น'])+'</span><span class="ln"></span></div><div class="df-note">'+esc(d.openingScene)+'</div>')
    :'';
}

function renderVitals(){
  var stats=d.stats||{};
  var R=20,CIRC=2*Math.PI*R;
  g('vitals-grid').innerHTML=STATS.map(function(s){
    var v=parseInt(stats[s[0]],10);if(isNaN(v))v=10;
    v=Math.max(0,Math.min(100,v));
    var off=CIRC-(v/100)*CIRC;
    var lbl=L==='th'?s[2]:s[1];
    return '<div class="df-dial-unit"><div class="df-dial-ring"><svg viewBox="0 0 48 48">'+
      '<circle class="df-dtrack" cx="24" cy="24" r="'+R+'"/>'+
      '<circle class="df-dfill" cx="24" cy="24" r="'+R+'" stroke-dasharray="'+CIRC+'" stroke-dashoffset="'+off+'"/></svg>'+
      '<div class="df-dval">'+v+'</div></div>'+
      '<div class="df-dlbl">'+lbl+'</div></div>';
  }).join('');
}

function renderFooter(){
  g('foot-file').textContent=t(STR.filePrefix)+(d.name?d.name.split(' ')[0]:t(STR.unnamed));
  g('foot-seq').textContent=d.pathway?((L==='th'?(PATHWAYS_TH[d.pathway]||d.pathway):d.pathway)+' Seq.'+(seq!=null?seq:9)):t(STR.unregistered);
}

function renderAll(){
  renderHeader();renderParticulars();renderStanding();renderSpirit();renderTies();renderPersona();renderVitals();renderFooter();
}

function setLang(lang){
  L=lang;
  document.documentElement.setAttribute('lang-mode',lang);
  qa('#lg-en,#lg-th').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-l')===lang)});
  qa('[data-en]').forEach(function(el){
    var v=lang==='th'?el.getAttribute('data-th'):el.getAttribute('data-en');
    if(v!=null)el.textContent=v;
  });
  renderAll();
}
